def create_branch_placements_and_transfer_rcs_id(apps, schema_editor):
    Role = apps.get_model('branches', 'Role')
    MemberRoleAssignment = apps.get_model('branches', 'MemberRoleAssignment')
    BranchMemberPlacement = apps.get_model('branches', 'BranchMemberPlacement')
    BranchPage = apps.get_model('branches', 'BranchPage')
    MemberListingPage = apps.get_model('branches', 'MemberListingPage')
    MemberProfile = apps.get_model('branches', 'MemberProfile')
    RolePlacement = apps.get_model('branches', 'RolePlacement')

    listing_pages = {}
    branch_path_map = {
        branch_page.path: branch_page.branch_type 
        for branch_page in BranchPage.objects.all()
    }
    for listing_page in MemberListingPage.objects.all():
        branch_path = listing_page.path[:-4]
        if branch_path in branch_path_map:
            listing_pages[branch_path_map[branch_path]] = listing_page

    for placement in BranchMemberPlacement.objects.all():
        for role_assignment in placement.role_assignments.all():
            role = role_assignment.role
            MemberRoleAssignment.objects.create(
                member = placement.member,
                role = role,
            )
            if listing_pages[role.branch]:
                RolePlacement.objects.create(
                    role=role,
                    page=listing_pages[role.branch],
                    display_name=role.name,
                    tier=next((i for i, entry in enumerate(Role._meta.get_field('tier').choices) if entry[0] == role.tier), None),
                )
    
    for role in Role.objects.all():
        if role.constituency_fsl != "none":
            role.constituency = role.constituency_fsl
        else:
            role.constituency = role.constituency_class
        role.role_code = (f"{role.branch}-{role.name}").lower().replace(' ', '-')
        role.save()

    # Transfer RCS ID
    i = 1
    for profile in MemberProfile.objects.all():
        if profile.email == "":
            profile.rcs_id = f"NULL{i}"
            i = i + 1
            sys.stdout.write(f"\n\033[93m\033[1mWARNING:\033[0m\033[93m Member '{profile.first_name} {profile.last_name}' has no email and has been assigned RCS ID '{profile.rcs_id}'.\033[0m")
            sys.stdout.flush()
        else:
            profile.rcs_id = str(profile.email).split('@', 1)[0]
        profile.save()


